/* ============================================================
   horses.js — Minato's stippled horses, as dots.

   His own pen drawing, traced dot for dot (about twenty thousand of them)
   so it can be drawn in pure black at any size: behind the monthly
   certificate (share/cert.js) and as one of the share card's backgrounds
   (share/card.js).

   Each dot is four bytes: twelve bits across, twelve down (both out of
   4095 over the drawing's own box) and eight for its width in quarter
   units. The drawing is 1381 by 1372 of those units.
   ============================================================ */
const W = 1381, H = 1372;
const PACKED = '';

let dots = null;
function unpack() {
  if (dots) return dots;
  const raw = atob(PACKED);
  const n = raw.length >> 2;
  dots = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) {
    const v = ((raw.charCodeAt(i * 4) << 24) | (raw.charCodeAt(i * 4 + 1) << 16) | (raw.charCodeAt(i * 4 + 2) << 8) | raw.charCodeAt(i * 4 + 3)) >>> 0;
    dots[i * 3] = (v >>> 20) / 4095 * W;
    dots[i * 3 + 1] = ((v >>> 8) & 4095) / 4095 * H;
    dots[i * 3 + 2] = (v & 255) / 4;          // the dot's radius
  }
  return dots;
}

/** How many dots the drawing has. */
export const horseDots = () => unpack().length / 3;

/* Drawing twenty thousand dots takes a moment, and a video asks for the same
   picture thirty times a second — so each size is drawn once and kept. */
const kept = new Map();
function horsesAt(w, colour) {
  w = Math.max(8, Math.round(w));
  const key = w + colour;
  if (kept.has(key)) return kept.get(key);
  const cv = document.createElement('canvas');
  cv.width = w; cv.height = Math.max(8, Math.round(w * H / W));
  const g = cv.getContext('2d');
  const d = unpack(), k = w / W;
  g.fillStyle = colour;
  g.beginPath();
  for (let i = 0; i < d.length; i += 3) {
    const x = d[i] * k, y = d[i + 1] * k, r = Math.max(0.42, d[i + 2] * k);
    g.moveTo(x + r, y);
    g.arc(x, y, r, 0, Math.PI * 2);
  }
  g.fill();
  if (kept.size >= 4) kept.delete(kept.keys().next().value);
  kept.set(key, cv);
  return cv;
}

/** The horses, as large as fits inside the box and centred in it. */
export function paintHorses(g, x, y, w, h, alpha = 1, colour = '#0A0A0A') {
  const k = Math.min(w / W, h / H);
  const dw = W * k, dh = H * k;
  const cv = horsesAt(dw, colour);
  g.save();
  g.globalAlpha *= alpha;
  g.drawImage(cv, x + (w - dw) / 2, y + (h - dh) / 2, dw, dh);
  g.restore();
}
